import {analyze,estimate,examples} from './engine.mjs';
const $=id=>document.getElementById(id);let current,quote,photoURL,worker,aiTimer;let quoteValid=true,aiBrief=null,aiRaw=null;
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500)}
function count(){$('count').textContent=`${$('request').value.length} / 6,000`}
$('request').addEventListener('input',count);
for(const b of document.querySelectorAll('[data-demo]'))b.onclick=()=>{$('request').value=examples[b.dataset.demo];$('trade').value='auto';count();document.querySelectorAll('[data-demo]').forEach(x=>x.classList.toggle('selected',x===b));};
function money(n){return new Intl.NumberFormat('en',{style:'currency',currency:$('currency').value}).format(n)}
function updateQuote(){try{quote=estimate({hours:$('hours').value||'invalid',rate:$('rate').value||'invalid',materials:$('parts').value||'invalid',callout:$('callout').value||'invalid',tax:$('tax').value||'invalid'});quoteValid=true;$('subtotal').textContent=money(quote.subtotal);$('tax-total').textContent=money(quote.taxAmount);$('total').textContent=money(quote.total);$('error').textContent='';}catch(e){quoteValid=false;quote=null;$('total').textContent='Check amounts';$('subtotal').textContent='—';$('tax-total').textContent='—';$('error').textContent=e.message;}}
for(const id of ['hours','rate','parts','callout','tax','currency'])$(id).addEventListener('input',updateQuote);
function stopAI(message='AI stopped. Your brief remains available.'){worker?.terminate();worker=null;clearTimeout(aiTimer);$('ai-button').disabled=false;$('cancel-ai').hidden=true;$('ai-status').textContent=message;}
$('cancel-ai').onclick=()=>stopAI();
$('job-form').onsubmit=e=>{e.preventDefault();try{current=analyze($('request').value,$('trade').value);stopAI('');$('ai-draft').hidden=true;aiBrief=null;aiRaw=null;for(const id of ['category','summary','problem','urgency','safety'])$(id).textContent=current[id];for(const id of ['materials','questions','steps']){$(id).replaceChildren(...current[id].map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));}$('urgency').classList.toggle('danger',current.urgency==='Immediate safety review');$('reply').value=current.response;$('results').hidden=false;$('empty').hidden=true;updateQuote();$('error').textContent='';if(innerWidth<1100)$('results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){$('error').textContent=e.message;}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('reply').value);toast('Reply copied');}catch{$('reply').focus();$('reply').select();toast('Select and copy the highlighted reply');}};
$('print').onclick=()=>window.print();
$('export').onclick=()=>{if(!current)return;if(!quoteValid){toast('Correct quote amounts before exporting.');return}const data={...current,response:$('reply').value,estimate:{...quote,currency:$('currency').value,status:'Illustrative, non-binding; review required'},aiAssessment:aiBrief||aiRaw||null,referencePhoto:photoURL?'Attached locally, excluded from export':'None',exportedAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='fieldbrief-job.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Job brief exported');};
function removePhoto(){if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;$('photo').value='';$('preview').removeAttribute('src');$('photo-preview').hidden=true;}
$('remove-photo').onclick=removePhoto;
$('photo').onchange=()=>{const f=$('photo').files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){removePhoto();$('error').textContent='Choose a JPG, PNG or WebP under 5 MB.';return}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(f);$('preview').src=photoURL;$('photo-preview').hidden=false;$('error').textContent='';};
$('ai-button').onclick=()=>{if(!current)return;$('ai-button').disabled=true;$('cancel-ai').hidden=false;$('ai-draft').hidden=true;$('ai-status').textContent='Loading free AI model. Keep this tab open…';try{worker ||=new Worker('./ai-worker.mjs',{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress')$('ai-status').textContent=data.text;if(data.type==='result'){clearTimeout(aiTimer);aiBrief=data.brief;aiRaw=data.text;$('ai-reply').value=data.brief?Object.entries(data.brief).map(([k,v])=>k.toUpperCase()+':\n'+(Array.isArray(v)?v.map(x=>'• '+x).join('\n'):v)).join('\n\n'):data.text;$('use-ai').hidden=!data.brief;$('ai-draft').hidden=false;$('ai-status').textContent=data.brief?'AI assessment ready. Review all statements before using.':'AI returned an incomplete format. Review the raw output; your original brief is unchanged.';$('ai-button').disabled=false;$('cancel-ai').hidden=true;}if(data.type==='error')stopAI(`AI unavailable: ${data.text}. The rule-based brief still works.`);};worker.onerror=()=>stopAI('AI could not load in this browser or network. The rule-based brief still works.');worker.postMessage({text:current.originalRequest,problem:current.problem,safety:current.safety});aiTimer=setTimeout(()=>stopAI('AI loading timed out after 3 minutes. You can retry on a faster connection/device.'),180000);}catch(e){stopAI(`AI unavailable: ${e.message}`);}};
$('use-ai').onclick=()=>{if(!aiBrief)return;$('reply').value=aiBrief.response;toast('AI draft selected — review before sending');};
window.addEventListener('beforeunload',()=>{worker?.terminate();if(photoURL)URL.revokeObjectURL(photoURL)});
